-- =============================================
-- Auth / Users & Import Configuration Tables
-- =============================================

CREATE TABLE IF NOT EXISTS "AppUsers" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Name" character varying(256) NOT NULL,
    "Email" character varying(256) NOT NULL,
    "Role" character varying(64) NOT NULL DEFAULT 'gestor',
    "PasswordHash" character varying(1024) NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_AppUsers_Email" ON "AppUsers" ("Email");
CREATE UNIQUE INDEX IF NOT EXISTS "IX_AppUsers_Name" ON "AppUsers" ("Name");

CREATE TABLE IF NOT EXISTS "ImportFileTypes" (
    "Id" uuid PRIMARY KEY,
    "Code" character varying(64) NOT NULL,
    "Name" character varying(256) NOT NULL,
    "Description" character varying(2000) NOT NULL,
    "AllowedExtensions" character varying(256) NOT NULL,
    "IsActive" boolean NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_ImportFileTypes_Code" ON "ImportFileTypes" ("Code");
CREATE INDEX IF NOT EXISTS "IX_ImportFileTypes_IsActive" ON "ImportFileTypes" ("IsActive");

INSERT INTO "ImportFileTypes" ("Id", "Code", "Name", "Description", "AllowedExtensions", "IsActive", "CreatedAt", "UpdatedAt")
