CREATE TABLE IF NOT EXISTS "ImportTemplatesV2" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "ImportFileTypeId" uuid NULL,
    "Name" character varying(256) NOT NULL,
    "Description" character varying(2000) NOT NULL,
    "IsActive" boolean NOT NULL,
    "FileNamePattern" character varying(256) NOT NULL,
    "RequiredHeadersCsv" character varying(2048) NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL
);
CREATE INDEX IF NOT EXISTS "IX_ImportTemplatesV2_IsActive" ON "ImportTemplatesV2" ("IsActive");
CREATE INDEX IF NOT EXISTS "IX_ImportTemplatesV2_ImportFileTypeId" ON "ImportTemplatesV2" ("ImportFileTypeId");

CREATE TABLE IF NOT EXISTS "ImportColumnMappings" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "ImportTemplateId" bigint NOT NULL,
    "SourceColumnName" character varying(256) NOT NULL,
    "TargetFieldName" character varying(256) NOT NULL,
    "IsRequired" boolean NOT NULL,
    "DefaultValue" character varying(4000) NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL
);
CREATE INDEX IF NOT EXISTS "IX_ImportColumnMappings_ImportTemplateId_TargetFieldName"
    ON "ImportColumnMappings" ("ImportTemplateId", "TargetFieldName");

CREATE TABLE IF NOT EXISTS "TransformRules" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Code" character varying(64) NOT NULL,
    "Name" character varying(128) NOT NULL,
    "Description" character varying(2000) NOT NULL,
    "IsActive" boolean NOT NULL DEFAULT true
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_TransformRules_Code" ON "TransformRules" ("Code");

CREATE TABLE IF NOT EXISTS "ColumnMappingTransformRules" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "ImportColumnMappingId" bigint NOT NULL,
    "TransformRuleId" bigint NOT NULL,
    "Order" integer NOT NULL,
    "IsEnabled" boolean NOT NULL DEFAULT true,
    "ParametersJson" jsonb NULL
);
CREATE INDEX IF NOT EXISTS "IX_ColumnMappingTransformRules_ImportColumnMappingId_Order"
    ON "ColumnMappingTransformRules" ("ImportColumnMappingId", "Order");
